# --- Positive: a valid ticket persists, snapshots assigned_rm_uid, and is RM-scoped --


def test_raise_allotment_ticket_persists_and_appears_only_for_its_assigned_rm(session):
    client_user = make_client(session, name="Cathy Client")
    rm_a = make_admin(session, AdminRole.RM, name="Ricky RM")
    rm_b = make_admin(session, AdminRole.RM, name="Robin RM")
    model = make_model(session, name="Alpha Model")
    set_assigned_rm(session, client_user, rm_a)

    svc = ClientPortalService(session)
    req = RaiseTicketReq(kind=TicketKind.ALLOTMENT, model_id=model.id, message="Please allot more.")
    result = svc.create_ticket(client_user.id, req)
    assert result.kind == TicketKind.ALLOTMENT

    rm_a_tickets = svc.list_rm_tickets(rm_uid=rm_a.firebase_uid, role=AdminRole.RM)
    rm_b_tickets = svc.list_rm_tickets(rm_uid=rm_b.firebase_uid, role=AdminRole.RM)
    assert len(rm_a_tickets) == 1
    assert all(isinstance(t, RmTicketDTO) for t in rm_a_tickets)
    assert rm_a_tickets[0].client_id == client_user.id
    assert rm_b_tickets == []


def test_admin_sees_every_ticket_a_superset_of_any_single_rms_view(session):
    client_user = make_client(session, name="Cathy Client")
    rm_a = make_admin(session, AdminRole.RM, name="Ricky RM")
    admin_user = make_admin(session, AdminRole.ADMIN, name="Andy Admin")
    model = make_model(session, name="Alpha Model")
    set_assigned_rm(session, client_user, rm_a)

    svc = ClientPortalService(session)
    svc.create_ticket(
        client_user.id, RaiseTicketReq(kind=TicketKind.ALLOTMENT, model_id=model.id, message="x")
    )

    rm_tickets = svc.list_rm_tickets(rm_uid=rm_a.firebase_uid, role=AdminRole.RM)
    admin_tickets = svc.list_rm_tickets(rm_uid=admin_user.firebase_uid, role=AdminRole.ADMIN)
    assert {t.ref for t in rm_tickets}.issubset({t.ref for t in admin_tickets})
    assert len(admin_tickets) >= len(rm_tickets)


# --- Positive: a status change stamps responded_by/responded_at ------------------


def test_set_rm_ticket_status_stamps_responder_and_timestamp(session):
    client_user = make_client(session, name="Cathy Client")
    rm = make_admin(session, AdminRole.RM, name="Ricky RM")
    model = make_model(session, name="Alpha Model")
    set_assigned_rm(session, client_user, rm)

    svc = ClientPortalService(session)
    created = svc.create_ticket(
        client_user.id, RaiseTicketReq(kind=TicketKind.ALLOTMENT, model_id=model.id, message="x")
    )
    updated = svc.set_rm_ticket_status(
        created.ref,
        RmTicketStatusReq(status=TicketStatus.IN_PROGRESS, note="Looking into it"),
        rm_uid=rm.firebase_uid,
        role=AdminRole.RM,
    )
    assert updated.status == TicketStatus.IN_PROGRESS
    assert updated.responded_by == rm.firebase_uid
    assert updated.responded_at is not None
    assert updated.response_note == "Looking into it"


