# --- Negative: a status change on a terminal ticket 409s -------------------------


@pytest.mark.parametrize("terminal_status", [TicketStatus.RESOLVED, TicketStatus.DECLINED])
def test_status_change_on_a_terminal_ticket_409s(session, terminal_status):
    client_user = make_client(session, name="Cathy Client")
    rm = make_admin(session, AdminRole.RM, name="Ricky RM")
    model = make_model(session, name="Alpha Model")
    set_assigned_rm(session, client_user, rm)

    svc = ClientPortalService(session)
    created = svc.create_ticket(
        client_user.id, RaiseTicketReq(kind=TicketKind.ALLOTMENT, model_id=model.id, message="x")
    )
    svc.set_rm_ticket_status(
        created.ref,
        RmTicketStatusReq(status=terminal_status),
        rm_uid=rm.firebase_uid,
        role=AdminRole.RM,
    )

    with pytest.raises(HTTPException) as exc_info:
        svc.set_rm_ticket_status(
            created.ref,
            RmTicketStatusReq(status=TicketStatus.IN_PROGRESS),
            rm_uid=rm.firebase_uid,
            role=AdminRole.RM,
        )
    assert exc_info.value.status_code == 409


# --- Negative: a non-owning, non-ADMIN RM fetching another RM's ticket 404s ------


def test_non_owning_rm_fetching_another_rms_ticket_gets_404(session):
    client_user = make_client(session, name="Cathy Client")
    owning_rm = make_admin(session, AdminRole.RM, name="Ricky RM")
    other_rm = make_admin(session, AdminRole.RM, name="Robin RM")
    model = make_model(session, name="Alpha Model")
    set_assigned_rm(session, client_user, owning_rm)

    svc = ClientPortalService(session)
    created = svc.create_ticket(
        client_user.id, RaiseTicketReq(kind=TicketKind.ALLOTMENT, model_id=model.id, message="x")
    )

    with pytest.raises(HTTPException) as exc_info:
        svc._require_rm_visible_ticket_dto(
            created.ref, rm_uid=other_rm.firebase_uid, role=AdminRole.RM
        )
    assert exc_info.value.status_code == 404


# --- Invariant: TicketStatus is exactly the frozen 5-member vocabulary -----------


def test_ticket_status_has_exactly_the_five_frozen_members():
    assert {s.value for s in TicketStatus} == {
        "new",
        "in_progress",
        "replied",
        "closed",
        "declined",
    }


